import{_ as c,C as o,o as d,c as p,a6 as n,E as s,j as t,a,w as u}from"./chunks/framework.5dd0l9Wo.js";const _=JSON.parse('{"title":"Business Logic Vulnerabilities · Case File 06","description":"Discover how applications break when real-world assumptions clash with software reality: negative quantities, coupon loops, and skipped workflow steps.","frontmatter":{"title":"Business Logic Vulnerabilities · Case File 06","description":"Discover how applications break when real-world assumptions clash with software reality: negative quantities, coupon loops, and skipped workflow steps."},"headers":[],"relativePath":"business-logic/index.md","filePath":"business-logic/index.md"}'),h={name:"business-logic/index.md"};function g(m,e,w,f,v,b){const i=o("LabGroup"),r=o("Term"),l=o("TopicComplete");return d(),p("div",null,[e[3]||(e[3]=n('<h1 id="business-logic-vulnerabilities-·-when-valid-code-does-invalid-things" tabindex="-1">Business Logic Vulnerabilities · When Valid Code Does Invalid Things <a class="header-anchor" href="#business-logic-vulnerabilities-·-when-valid-code-does-invalid-things" aria-label="Permalink to &quot;Business Logic Vulnerabilities · When Valid Code Does Invalid Things&quot;">​</a></h1><p class="wd-section-lede">Business logic vulnerabilities are uniquely deceptive: every single component can be running bug-free, perfectly syntax-validated, and cryptographically sound, yet the entire system remains completely broken. Logic flaws happen when developers build software around unspoken assumptions about how humans behave in the real world.</p><div class="wd-callout"><p><strong>💡 Everyday Analogy: The Vending Machine Return Slot.</strong> Imagine a vending machine where inserting $5 lets you purchase a $2 bottle of water, returning $3 in change. What happens if you press a button that requests <em>negative one bottles of water</em>? If the machine&#39;s computer calculates <code>Total = -1 × $2 = -$2</code> and computes your change as <code>Inserted ($5) - Total (-$2) = $7</code>, the machine just handed you free money! The math is technically consistent, but the real-world business rule—<em>&quot;a customer cannot buy negative goods&quot;</em>—was never written into the software.</p></div><h2 id="case-file-6-tracing-price-manipulation-behind-the-scenes" tabindex="-1">Case File #6: Tracing Price Manipulation Behind the Scenes <a class="header-anchor" href="#case-file-6-tracing-price-manipulation-behind-the-scenes" aria-label="Permalink to &quot;Case File #6: Tracing Price Manipulation Behind the Scenes&quot;">​</a></h2><p>Let&#39;s examine what happens when an online shopper adds an expensive luxury item to their cart:</p><div class="wd-case"><div class="wd-step wd-step--see"><span class="wd-step__tag">🔎 Step 1 · What You Notice in the Browser</span><p>You add a $1,337 leather jacket to your shopping cart. In your proxy history, you inspect the HTTP POST request sent when clicking &quot;Add to Cart&quot;: <code>productId=1&amp;price=133700&amp;quantity=1</code>.</p></div><div class="wd-step wd-step--server"><span class="wd-step__tag">⚙️ Step 2 · What the Server Does Behind the Scenes</span><p>The backend shopping cart handler receives the request parameters and computes the line-item total by multiplying the incoming price by the incoming quantity before storing it in the user&#39;s active session cart:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Server Computation Logic</span><span><span class="wd-code-input">Gold</span> = Parameter Trusted from Client</span></div><span class="wd-code-dev">item_price = </span><span class="wd-code-input">request.body.price</span><span class="wd-code-dev">; // Trusted straight from browser!<br>total_charge = item_price * request.body.quantity;<br>cart.append({ id: 1, total: total_charge });</span></div></div><div class="wd-step wd-step--break"><span class="wd-step__tag">💥 Step 3 · Where the Logic Breaks</span><p>The developers assumed the browser UI would always send the legitimate $1,337 price. By intercepting the request and changing <code>price=133700</code> to <code>price=1</code> (or sending a negative quantity to cancel out expensive items), the user pays a single penny for a luxury jacket. The checkout code validates that the user&#39;s payment covers the cart total, and the order ships!</p></div><div class="wd-step wd-step--fix"><span class="wd-step__tag">🛡️ Step 4 · How Developers Lock It Down</span><p>Never accept prices, discount flags, or financial figures from client HTTP requests. Look up the authoritative price directly from the database server-side using the product ID. Validate that all quantities are strictly positive integers within reasonable application boundaries.</p></div></div><h3 id="visual-comparison-ui-expectations-vs-proxy-reality" tabindex="-1">Visual Comparison: UI Expectations vs. Proxy Reality <a class="header-anchor" href="#visual-comparison-ui-expectations-vs-proxy-reality" aria-label="Permalink to &quot;Visual Comparison: UI Expectations vs. Proxy Reality&quot;">​</a></h3><div class="wd-compare"><div class="wd-compare__card wd-compare__card--expect"><span class="wd-compare__title">💭 What the Developer Expected</span><p>The web page dropdown only provides quantity choices from 1 to 10, and prices are rendered cleanly from our database, so no user could ever submit an invalid price or negative quantity.</p></div><div class="wd-compare__card wd-compare__card--actual"><span class="wd-compare__title">💥 What Actually Happened</span><p>The client controls the raw HTTP request completely. An attacker uses an intercepting proxy to modify prices, duplicate coupons, or skip prerequisite workflow steps entirely.</p></div></div><h3 id="the-integrity-checkpoints-of-a-multi-step-workflow" tabindex="-1">The Integrity Checkpoints of a Multi-Step Workflow <a class="header-anchor" href="#the-integrity-checkpoints-of-a-multi-step-workflow" aria-label="Permalink to &quot;The Integrity Checkpoints of a Multi-Step Workflow&quot;">​</a></h3><p>When handling transactions and workflows, a secure backend re-derives every authoritative truth at each step:</p><div class="wd-flow"><div class="wd-flow__node"><strong>1. Add to Cart</strong> Client supplies product ID; server fetches authoritative price from DB. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>2. Apply Discounts</strong> Enforce single-use coupon flags and prevent alternating discount loops. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>3. State Transition</strong> Verify order state is &#39;Awaiting Payment&#39; before moving to &#39;Completed&#39;. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--safe"><strong>4. Fulfillment</strong> Ship order only when payment gateway confirms full settlement. </div></div><hr><h2 id="client-side-controls-and-untrusted-inputs" tabindex="-1">Client-Side Controls and Untrusted Inputs <a class="header-anchor" href="#client-side-controls-and-untrusted-inputs" aria-label="Permalink to &quot;Client-Side Controls and Untrusted Inputs&quot;">​</a></h2><p>Client-side controls (like disabled HTML buttons, JavaScript validation, or hidden form fields) are visual conveniences for legitimate users, not security barriers. When an application trusts numbers supplied by the client:</p><ul><li><strong>Price Tampering:</strong> Setting the price to a negligible amount ($0.01) or zero.</li><li><strong>Negative Quantities:</strong> Ordering 1 expensive item ($1,000) and -99 cheap items ($10 each) to produce a net cart total of $10!</li><li><strong>Integer Limits &amp; Overflows:</strong> Submitting quantities so huge (e.g., above 2,147,483,647 in 32-bit signed integers) that the total wraps around to a negative number or zero.</li></ul>',15)),s(i,{ids:"business-logic-lab-logic-flaws-excessive-trust-in-client-side-controls, business-logic-lab-logic-flaws-high-level, business-logic-lab-logic-flaws-low-level"}),e[4]||(e[4]=n('<details class="details custom-block"><summary>🔬 Under the Hood: Why Integer Overflow Still Matters in Modern Apps</summary><p>In languages and databases using fixed-width integers (such as 32-bit signed integers in C, Java, or SQL <code>INT</code>), numbers wrap around when they exceed the maximum value: <code>2,147,483,647 + 1 = -2,147,483,648</code></p><p>If an e-commerce checkout multiplies <code>quantity × price</code> without bounds checking, an attacker can choose a quantity where the product wraps into a negative total. Many shopping cart engines interpret negative totals as store credits or treat any payment of $0 as paid in full.</p></details><hr><h2 id="coupons-refunds-and-rule-interactions" tabindex="-1">Coupons, Refunds, and Rule Interactions <a class="header-anchor" href="#coupons-refunds-and-rule-interactions" aria-label="Permalink to &quot;Coupons, Refunds, and Rule Interactions&quot;">​</a></h2><p>Logic flaws frequently hide in the seams between different business rules that make sense in isolation but break when combined:</p><ul><li><strong>Coupon Stacking Loops:</strong> A store offers two discount codes: <code>NEWCUSTOMER</code> (20% off) and <code>SPRING10</code> ($10 off). The UI prevents entering both. However, submitting alternating requests applies both codes repeatedly until the cart total drops to zero.</li><li><strong>Gift Card Balance Transfer:</strong> A gift card redemption endpoint deposits money into the user account without locking the card or checking if the card was already redeemed in the same session.</li><li><strong>Asymmetric Refunds:</strong> The system calculates a 30% discount on purchase, but the refund module refunds the original full catalog price upon return!</li></ul>',5)),s(i,{ids:"business-logic-lab-logic-flaws-flawed-enforcement-of-business-rules, business-logic-lab-logic-flaws-inconsistent-security-controls, business-logic-lab-logic-flaws-infinite-money"}),e[5]||(e[5]=t("hr",null,null,-1)),e[6]||(e[6]=t("h2",{id:"workflow-validation-and-flawed-state-machines",tabindex:"-1"},[a("Workflow Validation and Flawed State Machines "),t("a",{class:"header-anchor",href:"#workflow-validation-and-flawed-state-machines","aria-label":'Permalink to "Workflow Validation and Flawed State Machines"'},"​")],-1)),t("p",null,[e[1]||(e[1]=a("Applications frequently model complex workflows (checkout wizards, MFA logins, account registrations) as multi-step state machines. A ",-1)),s(r,{id:"state-machine-flaw"},{default:u(()=>[...e[0]||(e[0]=[a("state machine flaw",-1)])]),_:1}),e[2]||(e[2]=a(" occurs when the server assumes users will always proceed strictly through Step 1 → Step 2 → Step 3:",-1))]),e[7]||(e[7]=t("ul",null,[t("li",null,[t("strong",null,"Skipping Mandatory Steps:"),a(" Navigating directly to Step 3 ("),t("code",null,"/checkout/complete"),a(") without executing Step 2 ("),t("code",null,"/checkout/payment"),a(").")]),t("li",null,[t("strong",null,"Dual-Use Endpoints:"),a(" An endpoint designed for account registration is re-used for password updates without re-verifying the caller's existing password.")]),t("li",null,[t("strong",null,"Canceling Out of Mid-Flight States:"),a(" Aborting a 2FA prompt midway through login while retaining the initial authenticated session.")])],-1)),s(i,{ids:"business-logic-lab-logic-flaws-weak-isolation-on-dual-use-endpoint, business-logic-lab-logic-flaws-insufficient-workflow-validation, business-logic-lab-logic-flaws-authentication-bypass-via-flawed-state-machine"}),e[8]||(e[8]=n('<hr><h2 id="input-parsing-discrepancies-and-boundary-cases" tabindex="-1">Input Parsing Discrepancies and Boundary Cases <a class="header-anchor" href="#input-parsing-discrepancies-and-boundary-cases" aria-label="Permalink to &quot;Input Parsing Discrepancies and Boundary Cases&quot;">​</a></h2><p>When two different components in an architecture parse the exact same input using different rules, logic breaks down:</p><ul><li><strong>Email Normalization &amp; Truncation:</strong> A registration form accepts a 255-character email, but the database column only stores 100 characters. Submitting <code>admin@target.com.attacker.com</code> truncated at character 16 creates an account officially registered as <code>admin@target.com</code>!</li><li><strong>Domain Parsing Differences:</strong> An access-control filter checks if an email ends with <code>@target.com</code>, while the internal notification worker parses comments or subdomains differently.</li></ul>',4)),s(i,{ids:"business-logic-lab-logic-flaws-inconsistent-handling-of-exceptional-input, business-logic-lab-logic-flaws-bypassing-access-controls-using-email-address-parsing-discrepancies"}),e[9]||(e[9]=t("hr",null,null,-1)),e[10]||(e[10]=t("h2",{id:"cryptographic-oracles-in-business-flows",tabindex:"-1"},[a("Cryptographic Oracles in Business Flows "),t("a",{class:"header-anchor",href:"#cryptographic-oracles-in-business-flows","aria-label":'Permalink to "Cryptographic Oracles in Business Flows"'},"​")],-1)),e[11]||(e[11]=t("p",null,[a('When an application exposes endpoints that encrypt user data and later decrypt it (for example, generating encrypted cookies for "track my order" features), an investigator can use the application as an '),t("strong",null,"encryption oracle"),a(". By feeding crafted plaintext into the encryption helper and capturing the resulting ciphertext, they can forge administrative session tokens without ever knowing the server's private secret key.")],-1)),s(i,{ids:"business-logic-lab-logic-flaws-authentication-bypass-via-encryption-oracle"}),e[12]||(e[12]=n('<details class="details custom-block"><summary>⚙️ Engine Variations: How Frameworks Parse Duplicate Parameters</summary><p>When an HTTP request contains duplicate parameter names (<code>price=100&amp;price=0.01</code>):</p><ul><li><strong>PHP:</strong> Keeps the last value (<code>price=0.01</code>).</li><li><strong>ASP.NET:</strong> Concatenates all values with commas (<code>price=100,0.01</code>).</li><li><strong>Express / Node (qs):</strong> Converts duplicate parameters into an array (<code>price = [&#39;100&#39;, &#39;0.01&#39;]</code>).</li><li><strong>Java Servlets:</strong> Returns an array via <code>getParameterValues()</code> or the first value via <code>getParameter()</code>.</li></ul><p>If a security firewall checks the first parameter while the application processes the last, parameter pollution completely dismantles business validation.</p></details><div class="wd-callout wd-callout--warn"><p><strong>🛡️ Core Defensive Checklist:</strong> Re-derive all authoritative values server-side. Never trust prices, quantities, or privilege levels from the client. Enforce explicit state machine transition checks (ensure Step N cannot occur unless Step N-1 succeeded). Enforce database constraints (such as non-negative balance checks and unique coupon records), and audit business logic flows against concurrent and out-of-order execution.</p></div>',2)),s(l,{"topic-id":"business-logic-vulnerabilities",label:"Mark business logic complete"})])}const k=c(h,[["render",g]]);export{_ as __pageData,k as default};
